let sb,currentUser=null,currentProfile=null,currentPage="dashboard",permissions={},cache={drawings:[],wls:[],parts:[]};
let navSeq=0;
const $=id=>document.getElementById(id), esc=v=>String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
const admin=()=>currentProfile?.role==="Admin", can=(m,a)=>admin()||permissions[m]?.["can_"+a]===true;
const err=(id,t)=>{const e=$(id);if(e)e.innerHTML=`<div class="alert alert-error">${esc(t)}</div>`};
function showPortalError(message){const app=$("app");if(app)app.insertAdjacentHTML("beforeend",`<div class="portal-fatal" style="position:fixed;left:20px;right:20px;bottom:20px;z-index:99999;background:#fff1f1;border:1px solid #d33;border-radius:10px;padding:14px;color:#8b0000;font-weight:600;box-shadow:0 4px 18px rgba(0,0,0,.15)"><b>Portal error:</b> ${esc(message)}</div>`);}
window.addEventListener("error",e=>{console.error(e.error||e.message);showPortalError(e.message||"Unexpected JavaScript error");});
window.addEventListener("unhandledrejection",e=>{console.error(e.reason);showPortalError(e.reason?.message||String(e.reason||"Unhandled promise error"));});
async function withTimeout(promise,label="Page loading",ms=15000){let timer;const timeout=new Promise((_,rej)=>{timer=setTimeout(()=>rej(new Error(`${label} timed out. Please check Supabase connection/table permissions.`)),ms)});try{return await Promise.race([promise,timeout]);}finally{clearTimeout(timer);}}
async function loadProfile(){let r=await sb.from("user_profiles").select("*").eq("id",currentUser.id).maybeSingle();if(r.error)throw r.error;currentProfile=r.data}
async function loadPerms(){permissions={};if(admin())return;let r=await sb.from("user_module_permissions").select("*").eq("user_id",currentUser.id);if(r.error)throw r.error;(r.data||[]).forEach(x=>permissions[x.module]=x)}
async function start(){try{sb=supabase.createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY);let r=await sb.auth.getSession();if(r.data.session){currentUser=r.data.session.user;await loadProfile()}if(currentUser&&currentProfile?.approval_status==="Approved"){await loadPerms();render()}else if(currentUser)pending();else login()}catch(e){document.body.innerHTML=`<div class="auth"><div class="card auth-card"><h2>Portal error</h2><div class="alert alert-error">${esc(e.message)}</div></div></div>`}}
function login(){document.getElementById("app").innerHTML=`<div class="auth login-auth"><div class="auth-card login-card"><div class="login-brand"><img src="assets/mutha-logo.png" alt="Mutha Group"><div><h1>MUTHA GROUP NPD PORTAL</h1><p>New Product Development • Quality • Digital Transformation</p></div></div><div class="login-divider"></div><div id="lm"></div><form onsubmit="doLogin(event)"><div class="form-group"><label>Official Email</label><input id="le" type="email" placeholder="Enter official email" required></div><div class="form-group"><label>Password</label><input id="lp" type="password" placeholder="Enter password" required></div><button class="btn btn-primary login-btn">LOGIN</button></form><p class="login-register">New user? <button class="link-btn" onclick="register()">Register here</button></p></div><div class="login-developer"><img src="assets/developer-photo.png" alt="Developer"><div><span>PORTAL DEVELOPER</span><b>Mangesh Suresh Deshmukh</b><small>Quality & Development</small><small>9270717078</small><small>mfpl3dscan@muthagroup.com</small><a class="linkedin-btn" href="https://www.linkedin.com/in/mangesh-deshmukh-a15229373" target="_blank" rel="noopener noreferrer">in&nbsp; LinkedIn Profile</a></div></div></div>`}
async function doLogin(e){e.preventDefault();let r=await sb.auth.signInWithPassword({email:$("le").value.trim(),password:$("lp").value});if(r.error)return err("lm",r.error.message);currentUser=r.data.user;await loadProfile();if(!currentProfile||currentProfile.approval_status!=="Approved")return pending();await loadPerms();render()}
