const isDevelopmentAuditUser=()=>admin()||String(currentProfile?.department||'').toLowerCase()==='development';

const DEFAULT_PLANTS=['MFPL','MEPL-U3','MEPL-H21','MEPL-H25','DI','MSL','2020','2050','2070','Unassigned'];
const PLANT_MASTER=[['MFPL','MFPL'],['MEPL-U3','MEPL-U3'],['MEPL-H21','MEPL-H21'],['MEPL-H25','MEPL-H25'],['DI','DI'],['MSL','MSL'],['2020','2020 – Powder Coating (Bajaj/BAL Line)'],['2050','2050 – Sigma (TVS Line)'],['2070','2070 – Siddharth Engineering (Hero Line)'],['Unassigned','Unassigned']];
const DEFAULT_DEPARTMENTS=['Quality Assurance','Development','Production','Maintenance','Tool Room','Stores','Purchase','PPC','Engineering','Foundry','Machining','Dispatch / Logistics','HR / Admin','IT','Finance / Accounts','EHS / Safety','Sales / Marketing','Other'];
async function getRegistrationMasters(){let [p,d]=await Promise.all([sb.from('portal_plants').select('plant_name').eq('active',true).order('plant_name'),sb.from('portal_departments').select('department_name').eq('active',true).order('department_name')]);const dbPlants=(p.data||[]).map(x=>x.plant_name);return {plants:[...new Set([...DEFAULT_PLANTS,...dbPlants])],depts:(d.data||[]).map(x=>x.department_name).length?(d.data||[]).map(x=>x.department_name):DEFAULT_DEPARTMENTS}}
async function register(){let m=await getRegistrationMasters();document.getElementById("app").innerHTML=`<div class="auth"><div class="card auth-card"><div class="brand"><h1>USER REGISTRATION</h1><p>Enter correct employee, plant, department and contact details. Admin approval is required.</p></div><div id="rm"></div><form onsubmit="signup(event)"><div class="grid2"><div class="form-group"><label>Employee ID</label><input id="r_eid" required></div><div class="form-group"><label>Employee Name</label><input id="r_name" required></div><div class="form-group"><label>Department</label><select id="r_dept" required><option value="">Select Department</option>${m.depts.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="form-group"><label>Designation</label><input id="r_des" required></div><div class="form-group"><label>Plant / Unit</label><select id="r_plant" required><option value="">Select Plant / Unit</option>${m.plants.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="form-group"><label>Official Email</label><input id="r_email" type="email" required></div><div class="form-group"><label>WhatsApp / Mobile No.</label><input id="r_mobile" inputmode="numeric" pattern="[0-9+()\- ]{10,18}" placeholder="e.g. 919270717078" required></div><div class="form-group"><label>Reporting Manager</label><input id="r_manager" required></div><div class="form-group"><label><input id="r_wa" type="checkbox" checked> Receive WhatsApp updates</label></div><div class="form-group"><label><input id="r_em" type="checkbox" checked> Receive Email updates</label></div><div class="form-group"><label>Password</label><input id="r_pw" type="password" minlength="6" required></div><div class="form-group"><label>Confirm Password</label><input id="r_pw2" type="password" required></div></div><div class="actions"><button type="button" class="btn btn-secondary" onclick="login()">Back</button><button class="btn btn-primary">Register</button></div></form></div></div>`}
async function signup(e){e.preventDefault();if($("r_pw").value!==$("r_pw2").value)return err("rm","Passwords do not match");let mobile=$("r_mobile").value.trim();let digits=mobile.replace(/\D/g,'');if(digits.length<10||digits.length>15)return err('rm','Please enter a valid WhatsApp/mobile number.');let m={employee_id:$("r_eid").value.trim(),employee_name:$("r_name").value.trim(),department:$("r_dept").value,designation:$("r_des").value.trim(),plant_unit:$("r_plant").value,official_email:$("r_email").value.trim(),mobile_no:mobile,reporting_manager:$("r_manager").value.trim(),whatsapp_opt_in:$("r_wa").checked,email_opt_in:$("r_em").checked,requested_role:"Employee"};let r=await sb.auth.signUp({email:m.official_email,password:$("r_pw").value,data:m});if(r.error)return err("rm",r.error.message);document.getElementById("rm").innerHTML='<div class="alert alert-success">Registration submitted successfully. Admin will verify Plant, Department, role and module permissions before approval.</div>'}
function pending(){document.getElementById("app").innerHTML=`<div class="auth"><div class="card auth-card"><div class="brand"><h1>REGISTRATION PENDING</h1></div><div class="alert">Admin approval and module access assignment are pending.</div><button class="btn btn-primary" style="width:100%" onclick="logout()">Back to Login</button></div></div>`}
