function dwmRowsInProcess(rows){return (rows||[]).filter(x=>x.status==='In Process'||x.status==='In Progress').length}
function dwmRowsOnHold(rows){return (rows||[]).filter(x=>x.status==='On Hold').length}
function dwmRowsPostponed(rows){return (rows||[]).filter(x=>x.status==='Postponed').length}
