function devAuditStatusClass(v){
  const x=String(v||'Pending').toLowerCase();
  if(x==='conforming')return 'active';
  if(x==='nc'||x==='major nc'||x==='minor nc')return 'obsolete';
  if(x==='ofi')return 'review';
  return 'pending';
}
function renderDevelopmentAudit(){
  if(!isDevelopmentAuditUser())return $('main').innerHTML='<div class="alert alert-error">Development Department access required.</div>';
  const data=DEVELOPMENT_AUDIT_DATA;
  const saved=JSON.parse(localStorage.getItem('mutha_dev_audit_draft')||'{}');
  const statuses=saved.statuses||{};
  const remarks=saved.remarks||{};
  const sections=[...new Set(data.checklist.map(x=>x.section))];
  const hist=data.history||[];
  $('main').innerHTML=`<div class="page-title"><div><h1>Development Department Internal Audit</h1><p>Internal Department Audit Checklist – Development & Pattern Shop • ISO 9001:2015 / IATF 16949:2016</p></div><div class="actions-inline"><button class="btn btn-secondary" onclick="devAuditExport()">Export CSV</button><button class="btn btn-secondary" onclick="devAuditReset()">Reset Draft</button><button class="btn btn-primary" onclick="devAuditSave()">Save Draft</button></div></div>
  <div class="panel audit-meta-panel"><div class="audit-meta-grid">
    <div class="form-group"><label>Format No.</label><input value="MF-L-DEVP-17" readonly></div>
    <div class="form-group"><label>Revision No.</label><input value="00" readonly></div>
    <div class="form-group"><label>Revision Date</label><input value="07-Jul-2026" readonly></div>
    <div class="form-group"><label>Department</label><input value="Development & Pattern Shop" readonly></div>
    <div class="form-group"><label>Audit No.</label><input id="dev_audit_no" value="${esc(saved.audit_no||'IA/DEVP/2026/03')}"></div>
    <div class="form-group"><label>Audit Plan Date</label><input id="dev_plan_date" type="date" value="${esc(saved.plan_date||'')}"></div>
    <div class="form-group"><label>Audit Actual Date</label><input id="dev_actual_date" type="date" value="${esc(saved.actual_date||'')}"></div>
    <div class="form-group"><label>Lead Auditor</label><input id="dev_auditor" value="${esc(saved.auditor||currentProfile?.employee_name||'')}"></div>
  </div></div>
  <div class="audit-kpis" id="dev_audit_kpis"></div>
  <div class="panel"><div class="page-title audit-history-title"><div><h3>Previous Audit History</h3><p class="small">Imported from the Development Department audit workbook.</p></div></div>
  <div class="tablewrap audit-history-wrap"><table><thead><tr><th>Audit No.</th><th>Plan Date</th><th>Actual Date</th><th>Total</th><th>Conforming</th><th>NC</th><th>OFI</th><th>Major NC</th><th>Minor NC</th></tr></thead><tbody>${hist.map(x=>`<tr><td>${esc(x.audit_no)}</td><td>${x.plan_date?new Date(x.plan_date).toLocaleDateString():'-'}</td><td>${x.actual_date?new Date(x.actual_date).toLocaleDateString():'-'}</td><td>${esc(x.total??'-')}</td><td>${esc(x.conforming??'-')}</td><td>${esc(x.nc??'-')}</td><td>${esc(x.ofi??'-')}</td><td>${esc(x.major_nc??'-')}</td><td>${esc(x.minor_nc??'-')}</td></tr>`).join('')}</tbody></table></div></div>
  <div class="panel"><div class="audit-filterbar"><input id="dev_audit_q" placeholder="Search checkpoint, clause, evidence..." oninput="renderDevAuditRows()"><select id="dev_audit_section" onchange="renderDevAuditRows()"><option value="">All Sections</option>${sections.map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="dev_audit_result" onchange="renderDevAuditRows()"><option value="">All Results</option><option>Pending</option><option>Conforming</option><option>NC</option><option>OFI</option><option>Major NC</option><option>Minor NC</option></select></div>
  <div class="tablewrap dev-audit-tablewrap"><table><thead><tr><th>#</th><th>Section</th><th>Audit Check Point</th><th>ISO / IATF Clause</th><th>Auditor – What to Check?</th><th>How to Check?</th><th>Evidence / Record</th><th>Result</th><th>Remarks / NC Details</th><th>Responsibility</th><th>Target</th><th>Closure</th></tr></thead><tbody id="dev_audit_rows"></tbody></table></div></div>`;
  renderDevAuditRows();
}
function renderDevAuditRows(){
  const q=String($('dev_audit_q')?.value||'').toLowerCase();
  const sec=$('dev_audit_section')?.value||'';
  const rf=$('dev_audit_result')?.value||'';
  const saved=JSON.parse(localStorage.getItem('mutha_dev_audit_draft')||'{}');
  const statuses=saved.statuses||{}, remarks=saved.remarks||{};
  const rows=DEVELOPMENT_AUDIT_DATA.checklist.filter(x=>(!sec||x.section===sec)&&(!rf||(statuses[x.no]||'Pending')===rf)&&(!q||[x.section,x.checkpoint,x.clause,x.what,x.method,x.evidence].join(' ').toLowerCase().includes(q)));
  $('dev_audit_rows').innerHTML=rows.map(x=>{const st=statuses[x.no]||'Pending';return `<tr><td>${x.no}</td><td>${esc(x.section)}</td><td>${esc(x.checkpoint)}</td><td>${esc(x.clause)}</td><td>${esc(x.what)}</td><td>${esc(x.method)}</td><td>${esc(x.evidence)}</td><td><select class="audit-result-select badge ${devAuditStatusClass(st)}" data-audit-no="${x.no}" onchange="devAuditChange(${x.no},this.value)"><option ${st==='Pending'?'selected':''}>Pending</option><option ${st==='Conforming'?'selected':''}>Conforming</option><option ${st==='NC'?'selected':''}>NC</option><option ${st==='OFI'?'selected':''}>OFI</option><option ${st==='Major NC'?'selected':''}>Major NC</option><option ${st==='Minor NC'?'selected':''}>Minor NC</option></select></td><td><input class="audit-remark-input" value="${esc(remarks[x.no]||'')}" placeholder="Enter remarks / evidence" onchange="devAuditRemark(${x.no},this.value)"></td><td><input class="audit-small-input" value="${esc(saved.responsibility?.[x.no]||x.responsibility||'')}" onchange="devAuditResp(${x.no},this.value)"></td><td>${esc(x.target||'-')}</td><td><input class="audit-small-input" value="${esc(saved.closure?.[x.no]||x.closure||'')}" onchange="devAuditClosure(${x.no},this.value)"></td></tr>`}).join('')||'<tr><td colspan="12" class="empty">No matching checkpoints.</td></tr>';
  updateDevAuditKpis();
}
function devAuditState(){
  return JSON.parse(localStorage.getItem('mutha_dev_audit_draft')||'{}');
}
function saveDevAuditState(s){localStorage.setItem('mutha_dev_audit_draft',JSON.stringify(s));}
function devAuditChange(no,val){const s=devAuditState();s.statuses=s.statuses||{};s.statuses[no]=val;saveDevAuditState(s);updateDevAuditKpis();}
function devAuditRemark(no,val){const s=devAuditState();s.remarks=s.remarks||{};s.remarks[no]=val;saveDevAuditState(s);}
function devAuditResp(no,val){const s=devAuditState();s.responsibility=s.responsibility||{};s.responsibility[no]=val;saveDevAuditState(s);}
function devAuditClosure(no,val){const s=devAuditState();s.closure=s.closure||{};s.closure[no]=val;saveDevAuditState(s);}
function updateDevAuditKpis(){
  const s=devAuditState(), st=s.statuses||{}, vals=DEVELOPMENT_AUDIT_DATA.checklist.map(x=>st[x.no]||'Pending');
  const counts={Pending:0,Conforming:0,NC:0,OFI:0,'Major NC':0,'Minor NC':0};vals.forEach(v=>counts[v]=(counts[v]||0)+1);
  const k=$('dev_audit_kpis'); if(!k)return;
  k.innerHTML=`<div><b>${vals.length}</b><span>Total Checkpoints</span></div><div class="good"><b>${counts.Conforming}</b><span>Conforming</span></div><div class="bad"><b>${counts.NC+counts['Major NC']+counts['Minor NC']}</b><span>NC</span></div><div class="ofi"><b>${counts.OFI}</b><span>OFI</span></div><div class="pending"><b>${counts.Pending}</b><span>Pending</span></div>`;
}
function devAuditSave(){
  const s=devAuditState();
  s.audit_no=$('dev_audit_no')?.value||'';s.plan_date=$('dev_plan_date')?.value||'';s.actual_date=$('dev_actual_date')?.value||'';s.auditor=$('dev_auditor')?.value||'';
  saveDevAuditState(s);alert('Development Internal Audit draft saved on this browser.');
}
function devAuditReset(){if(!confirm('Reset the Development Internal Audit draft on this browser?'))return;localStorage.removeItem('mutha_dev_audit_draft');renderDevelopmentAudit();}
function devAuditExport(){
  const s=devAuditState(), rows=DEVELOPMENT_AUDIT_DATA.checklist.map(x=>({No:x.no,Section:x.section,Checkpoint:x.checkpoint,Clause:x.clause,What_to_Check:x.what,Method:x.method,Evidence:x.evidence,Result:s.statuses?.[x.no]||'Pending',Remarks:s.remarks?.[x.no]||'',Responsibility:s.responsibility?.[x.no]||x.responsibility||'',Target:x.target||'',Closure:s.closure?.[x.no]||x.closure||''}));
  csvExportWithApproval('Development Internal Audit',`Development_Internal_Audit_${new Date().toISOString().slice(0,10)}`,()=>downloadCsvRows(rows,`Development_Internal_Audit_${new Date().toISOString().slice(0,10)}`));
}
async function dev_audit(seq=navSeq){renderDevelopmentAudit();}



function ganttStatusClass(st){return ({'Completed':'gantt-status-completed','In Progress':'gantt-status-progress','Planned':'gantt-status-planned','Delayed':'gantt-status-delayed'})[st]||'gantt-status-planned'}
function ganttWeekOptions(selected=''){const g=window._ganttData||DEVELOPMENT_GANTT;return (g.weeks||[]).map((w,i)=>`<option value="${i}" ${String(i)===String(selected)?'selected':''}>${esc((g.months||[])[i]||'')} ${esc(w)}</option>`).join('')}
function ganttPlanWeeks(start,end){const g=window._ganttData||DEVELOPMENT_GANTT;const a=Number(start),b=Number(end);return (g.weeks||[]).map((_,i)=>(Number.isFinite(a)&&Number.isFinite(b)&&i>=a&&i<=b)?'Plan':'')}
function renderGantt(){
 const g=window._ganttData||DEVELOPMENT_GANTT, acts=g.activities||[];
 const counts={Planned:0,'In Progress':0,Completed:0,Delayed:0};acts.forEach(x=>counts[x.status||'Planned']=(counts[x.status||'Planned']||0)+1);
 $('main').innerHTML=`<div class="page-title"><div><h1>📊 Development Gantt Chart</h1><p>${esc(g.title||'Development Schedule')} • ${esc(g.period||'Prepared in portal')}</p></div><div class="actions-inline"><button class="btn btn-primary" onclick="openGanttActivityForm()">＋ Add Activity</button></div></div>
 <div class="panel gantt-summary"><div class="request-cards"><div><b>${acts.length}</b><span>Total Activities</span></div><div><b>${counts.Planned||0}</b><span>Planned</span></div><div><b>${counts['In Progress']||0}</b><span>In Process</span></div><div><b>${counts.Completed||0}</b><span>Completed</span></div><div><b>${counts.Delayed||0}</b><span>Delayed / Replan</span></div></div></div>
 <div class="panel"><div class="gantt-toolbar"><input id="gantt_q" placeholder="Search activity / responsible..." oninput="renderGanttRows()"><button class="btn btn-secondary" onclick="$('gantt_q').value='';renderGanttRows()">Clear</button><span class="gantt-legend"><span class="legend-plan">PLAN</span><span class="legend-actual">ACTUAL</span></span></div>
 <div class="gantt-wrap gantt-excel-wrap"><table class="gantt-table gantt-excel-table"><thead><tr><th rowspan="2" class="gantt-no">No.</th><th rowspan="2" class="gantt-activity">Activity planned</th><th rowspan="2">Responsible</th><th rowspan="2">Status</th><th rowspan="2" class="gantt-type">Type</th>${(g.weeks||[]).map((w,i)=>`<th><div>${esc((g.months||[])[i]||'')}</div><b>${esc(w)}</b></th>`).join('')}<th rowspan="2">Action</th></tr><tr class="gantt-subhead">${(g.weeks||[]).map(()=>'<th>Week</th>').join('')}</tr></thead><tbody id="gantt_rows"></tbody></table></div>
 <div class="small gantt-note">Gantt is prepared and maintained directly in the portal. No Excel import is required. Use <b>Update / Replan</b> whenever dates or sequence change and enter the reason.</div></div>`;renderGanttRows();
}
function renderGanttRows(){const g=window._ganttData||DEVELOPMENT_GANTT;const q=String($('gantt_q')?.value||'').toLowerCase();const rows=(g.activities||[]).filter(x=>!q||[x.activity,x.responsible,x.status].join(' ').toLowerCase().includes(q));$('gantt_rows').innerHTML=rows.map(x=>{const plan=x.weeks||[];const status=x.status||'Planned';return `<tr class="gantt-plan-row"><td rowspan="2">${esc(x.no)}</td><td rowspan="2" class="gantt-activity-cell"><b>${esc(x.activity)}</b>${x.replan_reason?`<br><small>Replan: ${esc(x.replan_reason)}</small>`:''}</td><td rowspan="2">${esc(x.responsible||'-')}</td><td rowspan="2"><span class="gantt-status ${ganttStatusClass(status)}">${esc(status)}</span></td><td class="gantt-type-cell"><b>P</b></td>${plan.map(v=>`<td class="${v==='Plan'?'gantt-plan':''}">${v==='Plan'?'<span>PLAN</span>':''}</td>`).join('')}<td rowspan="2"><button class="btn btn-secondary" onclick="openGanttUpdate(${x.no})">Update / Replan</button></td></tr><tr class="gantt-actual-row"><td class="gantt-type-cell"><b>A</b></td>${plan.map(()=>`<td class="gantt-actual-cell"></td>`).join('')}</tr>`}).join('')||'<tr><td colspan="20" class="empty">No matching activities.</td></tr>'}
function openGanttActivityForm(){const g=window._ganttData||DEVELOPMENT_GANTT;$('app').insertAdjacentHTML('beforeend',`<div class="modal-bg" id="modal"><div class="modal wide-modal"><div class="modal-header"><div><h2>＋ Prepare Gantt Activity</h2><p class="small">Create the development plan directly in the portal.</p></div><button class="close" onclick="closeM()">×</button></div><div class="grid2"><div class="form-group full"><label>Activity *</label><input id="ga_name" placeholder="e.g. Pattern Manufacturing"></div><div class="form-group"><label>Responsible</label><input id="ga_owner"></div><div class="form-group"><label>Status</label><select id="ga_status"><option>Planned</option><option>In Progress</option><option>Completed</option><option>Delayed</option></select></div><div class="form-group"><label>Start Week</label><select id="ga_start">${ganttWeekOptions(0)}</select></div><div class="form-group"><label>End Week</label><select id="ga_end">${ganttWeekOptions(0)}</select></div><div class="form-group full"><label>Remarks</label><textarea id="ga_remark" placeholder="Planning remarks"></textarea></div></div><div class="actions"><button class="btn btn-secondary" onclick="closeM()">Cancel</button><button class="btn btn-primary" onclick="saveGanttActivity()">Prepare Activity</button></div></div></div>`)}
function saveGanttActivity(){const g=window._ganttData||DEVELOPMENT_GANTT;const a=$('ga_name')?.value.trim();if(!a)return alert('Activity is required.');let st=Number($('ga_start')?.value||0),en=Number($('ga_end')?.value||st);if(en<st)[st,en]=[en,st];g.activities=[...(g.activities||[]),{no:(g.activities?.length||0)+1,activity:a,weeks:ganttPlanWeeks(st,en),responsible:$('ga_owner')?.value||'',status:$('ga_status')?.value||'Planned',remark:$('ga_remark')?.value||'',replan_reason:''}];window._ganttData=g;localStorage.setItem('mutha_gantt_data',JSON.stringify(g));closeM();renderGantt()}
function openGanttUpdate(no){const g=window._ganttData||DEVELOPMENT_GANTT,x=(g.activities||[]).find(a=>Number(a.no)===Number(no));if(!x)return;const first=Math.max(0,(x.weeks||[]).findIndex(v=>v==='Plan')),last=Math.max(first,(x.weeks||[]).map(v=>v==='Plan').lastIndexOf(true));$('app').insertAdjacentHTML('beforeend',`<div class="modal-bg" id="modal"><div class="modal wide-modal"><div class="modal-header"><div><h2>🔄 Update / Replan Activity</h2><p class="small">${esc(x.activity)}</p></div><button class="close" onclick="closeM()">×</button></div><div class="grid2"><div class="form-group full"><label>Activity</label><input id="gu_name" value="${esc(x.activity)}"></div><div class="form-group"><label>Responsible</label><input id="gu_owner" value="${esc(x.responsible||'')}"></div><div class="form-group"><label>Status</label><select id="gu_status">${['Planned','In Progress','Completed','Delayed'].map(v=>`<option ${v===(x.status||'Planned')?'selected':''}>${v}</option>`).join('')}</select></div><div class="form-group"><label>Replanned Start Week</label><select id="gu_start">${ganttWeekOptions(first)}</select></div><div class="form-group"><label>Replanned End Week</label><select id="gu_end">${ganttWeekOptions(last)}</select></div><div class="form-group full"><label>Update / Replan Reason *</label><textarea id="gu_reason" required placeholder="Reason for timing / sequence / target change"></textarea></div></div><div class="actions"><button class="btn btn-secondary" onclick="closeM()">Cancel</button><button class="btn btn-primary" onclick="saveGanttUpdate(${x.no})">Save Update / Replan</button></div></div></div>`)}
function saveGanttUpdate(no){const g=window._ganttData||DEVELOPMENT_GANTT,x=(g.activities||[]).find(a=>Number(a.no)===Number(no));if(!x)return;const reason=$('gu_reason')?.value.trim();if(!reason)return alert('Please enter the update / replan reason.');let st=Number($('gu_start').value||0),en=Number($('gu_end').value||st);if(en<st)[st,en]=[en,st];x.activity=$('gu_name').value.trim()||x.activity;x.responsible=$('gu_owner').value.trim();x.status=$('gu_status').value;x.weeks=ganttPlanWeeks(st,en);x.replan_reason=reason;x.updated_at=new Date().toISOString();window._ganttData=g;localStorage.setItem('mutha_gantt_data',JSON.stringify(g));closeM();renderGantt()}
function exportGantt(){const g=window._ganttData||DEVELOPMENT_GANTT;const rows=(g.activities||[]).map(x=>({No:x.no,Activity:x.activity,Responsible:x.responsible||'',Status:x.status||'Planned',Replan_Reason:x.replan_reason||'',Timeline:(x.weeks||[]).map((v,i)=>v==='Plan'?`${(g.months||[])[i]||''} ${(g.weeks||[])[i]||''}`.trim():'').filter(Boolean).join(', ')}));exportRows(rows,'Gantt_Activities','csv')}

async function gantt(seq=navSeq){try{const s=localStorage.getItem('mutha_gantt_data');if(s)window._ganttData=JSON.parse(s)}catch(e){}renderGantt();}

function canManageLevel3(){
  return admin() || String(currentProfile?.department||'').toLowerCase()==='development';
}
let level3RowsCache=[];
async function loadLevel3Rows(){
  let r=await sb.from("portal_level3_documents").select("*").order("created_at",{ascending:false});
  if(r.error){
    // Table may not have been created yet; continue with the supplied controlled master.
    level3RowsCache=[...LEVEL3_WORK_INSTRUCTIONS];
    return {error:r.error};
  }
  const dbRows=(r.data||[]).map(x=>({
    id:x.id, format_no:x.format_no, title:x.title, issue_date:x.issue_date||'', revision:x.revision||'',
    purpose:x.purpose||'', scope:x.scope||'', owner:x.owner||'', procedure:x.procedure_steps||'',
    status:x.status||'Active', source:'portal', created_by:x.created_by
  }));
  level3RowsCache=[...dbRows,...LEVEL3_WORK_INSTRUCTIONS.filter(w=>!dbRows.some(d=>d.format_no===w.format_no))];
  return {error:null};
}

