function copyWIHistory(){
  const idx=Number($('wi_copy')?.value);
  if(!Number.isFinite(idx)||!level3RowsCache[idx])return;
  const x=level3RowsCache[idx];
  $('wi_title').value=x.title||'';$('wi_owner_new').value=x.owner||'';$('wi_purpose').value=x.purpose||'';$('wi_scope').value=x.scope||'';$('wi_proc').value=x.procedure||'';$('wi_rev').value=x.revision||'';
}
async function saveWI(){
  const payload={format_no:$('wi_fno')?.value.trim(),title:$('wi_title')?.value.trim(),issue_date:$('wi_date')?.value||null,revision:$('wi_rev')?.value.trim(),owner:$('wi_owner_new')?.value.trim(),status:$('wi_status')?.value||'Draft',purpose:$('wi_purpose')?.value.trim(),scope:$('wi_scope')?.value.trim(),procedure_steps:$('wi_proc')?.value.trim(),created_by:currentUser.id,created_by_name:currentProfile.employee_name};
  if(!payload.format_no||!payload.title){alert('Format No. and Title are required.');return}
  const r=await sb.from("portal_level3_documents").insert(payload).select().single();
  if(r.error){alert(r.error.message);return}
  closeM();await loadLevel3Rows();renderLevel3();
}
async function editWI(i){
  const x=level3RowsCache[i]; if(!x||x.source!=='portal')return;
  $('app').insertAdjacentHTML('beforeend',`<div class="modal-bg" id="modal"><div class="modal wi-form-modal"><div class="modal-header"><div><h2>✏️ Edit Work Instruction</h2><p class="small">${esc(x.format_no)}</p></div><button class="close" onclick="closeM()">×</button></div><div class="wi-form-grid">
  <div><label>Format No.</label><input id="wi_fno" value="${esc(x.format_no)}"></div><div><label>Title</label><input id="wi_title" value="${esc(x.title)}"></div>
  <div><label>Issue Date</label><input id="wi_date" type="date" value="${esc(x.issue_date)}"></div><div><label>Revision</label><input id="wi_rev" value="${esc(x.revision)}"></div>
  <div><label>Owner</label><input id="wi_owner_new" value="${esc(x.owner)}"></div><div><label>Status</label><select id="wi_status"><option ${x.status==='Draft'?'selected':''}>Draft</option><option ${x.status==='Active'?'selected':''}>Active</option><option ${x.status==='Obsolete'?'selected':''}>Obsolete</option></select></div>
  <div class="full"><label>Purpose</label><textarea id="wi_purpose" rows="3">${esc(x.purpose)}</textarea></div><div class="full"><label>Scope</label><textarea id="wi_scope" rows="3">${esc(x.scope)}</textarea></div><div class="full"><label>Procedure / Work Steps</label><textarea id="wi_proc" rows="7">${esc(x.procedure)}</textarea></div>
  <div class="full actions"><button class="btn btn-primary" onclick="updateWI('${esc(x.id)}')">Update Work Instruction</button><button class="btn btn-secondary" onclick="closeM()">Cancel</button></div>
  </div></div></div>`);
}
async function updateWI(id){
  const payload={format_no:$('wi_fno')?.value.trim(),title:$('wi_title')?.value.trim(),issue_date:$('wi_date')?.value||null,revision:$('wi_rev')?.value.trim(),owner:$('wi_owner_new')?.value.trim(),status:$('wi_status')?.value||'Active',purpose:$('wi_purpose')?.value.trim(),scope:$('wi_scope')?.value.trim(),procedure_steps:$('wi_proc')?.value.trim()};
  const r=await sb.from("portal_level3_documents").update(payload).eq("id",id).select().single();
  if(r.error){alert(r.error.message);return}
  closeM();await loadLevel3Rows();renderLevel3();
}
async function deleteWI(id){
  if(!confirm('Delete this portal-created Work Instruction?'))return;
  const r=await sb.from("portal_level3_documents").delete().eq("id",id);
  if(r.error){alert(r.error.message);return}
  await loadLevel3Rows();renderLevel3();
}
async function level3(seq=navSeq){try{const s=localStorage.getItem('mutha_level3_workbook');if(s)window._uploadedLevel3Workbook=JSON.parse(s)}catch(e){}await loadLevel3Rows();if(seq!==navSeq)return;renderLevel3();}

async function audit(seq=navSeq){if(!admin())return;let [a,h,n]=await Promise.all([sb.from("portal_audit_log").select("*").order("created_at",{ascending:false}).limit(250),sb.from("portal_admin_history").select("*").order("created_at",{ascending:false}).limit(250),sb.from("portal_notifications").select("*").order("created_at",{ascending:false}).limit(250)]);if(seq!==navSeq)return;if(a.error)return $("main").innerHTML=`<div class="alert alert-error">${esc(a.error.message)}</div>`;$('main').innerHTML=`<div class="page-title"><div><h1>Admin – Complete Update History</h1><p>All portal record updates, user/profile changes, access changes and notification status are traceable here.</p></div></div><div class="panel"><h3>Register / Scanning Updates</h3><div class="tablewrap"><table><thead><tr><th>Date</th><th>Module</th><th>Action</th><th>Record</th><th>User</th><th>Email</th><th>WhatsApp</th></tr></thead><tbody>${(a.data||[]).map(x=>`<tr><td>${new Date(x.created_at).toLocaleString()}</td><td>${esc(x.module)}</td><td>${esc(x.action)}</td><td>${esc(x.record_label)}</td><td>${esc(x.actor_name)}</td><td>${esc(x.actor_email||'-')}</td><td>${x.actor_mobile?`<button class="btn btn-secondary" onclick="wa('${esc(x.actor_mobile)}','Mutha Quality Portal: ${esc(x.module)} ${esc(x.action.toLowerCase())} - ${esc(x.record_label)} updated by ${esc(x.actor_name)}.')">Open</button>`:'-'}</td></tr>`).join('')||'<tr><td colspan="7">No updates.</td></tr>'}</tbody></table></div></div><div class="panel"><h3>User / Permission History</h3><div class="tablewrap"><table><thead><tr><th>Date</th><th>Entity</th><th>Action</th><th>Target User</th><th>Changed By</th><th>Description</th></tr></thead><tbody>${(h.data||[]).map(x=>`<tr><td>${new Date(x.created_at).toLocaleString()}</td><td>${esc(x.entity_type)}</td><td>${esc(x.action)}</td><td>${esc(x.target_user_id||'-')}</td><td>${esc(x.actor_name||'-')}<br>${esc(x.actor_email||'-')}</td><td>${esc(x.description||'-')}</td></tr>`).join('')||'<tr><td colspan="6">No user history.</td></tr>'}</tbody></table></div></div><div class="panel"><h3>Email / WhatsApp Notification Queue</h3><div class="tablewrap"><table><thead><tr><th>Date</th><th>Channel</th><th>Recipient</th><th>Event</th><th>Status</th><th>Message</th><th>Sent</th></tr></thead><tbody>${(n.data||[]).map(x=>`<tr><td>${new Date(x.created_at).toLocaleString()}</td><td>${esc(x.channel)}</td><td>${esc(x.recipient_name||'-')}<br>${esc(x.recipient_email||x.recipient_mobile||'-')}</td><td>${esc(x.event_type)}</td><td>${esc(x.status)}</td><td>${esc(x.message)}</td><td>${x.sent_at?new Date(x.sent_at).toLocaleString():'-'}</td></tr>`).join('')||'<tr><td colspan="7">No notifications.</td></tr>'}</tbody></table></div></div><div class="panel"><p class="small">Automatic outbound email/WhatsApp requires an approved email provider and WhatsApp Business API. The portal stores every notification in this queue so Admin can track Pending/Sent/Failed status. Until the provider is connected, Admin can use Open WhatsApp from the update history.</p></div>`}
