 const rows=r.data||[]; window._scanPlans=rows;
 const today=new Date().toISOString().slice(0,10);
 const counts={planned:rows.filter(x=>['Planned','In Process'].includes(x.status)).length,overdue:rows.filter(x=>x.status!=='Completed'&&x.planned_date&&x.planned_date<today).length,completed:rows.filter(x=>x.status==='Completed').length};
 $('main').innerHTML=`<div class="page-title"><div><h1>🗓 Planned Scanning Activities</h1><p>Plan normal and periodic 3D scanning activities from development through production tooling life.</p></div>${can(m,'add')?`<button class="btn btn-primary" onclick="scanPlanForm()">＋ Add Scanning Plan</button>`:''}<button class="btn btn-secondary" onclick="exportRows(window._scanPlans||[],'3D_Scanning_Planning','xlsx')">⬇ Excel</button></div>
 <div class="subtabs scanning-subtabs"><button class="subtab" onclick="scanning()">📊 Daily Scan Plan</button><button class="subtab active" onclick="scanningPlanning()">🗓 Planned Scanning Activities</button>${admin()?`<button class="subtab" onclick="manageScanEngineers()">👷 Manage Engineers</button><button class="subtab" onclick="cycleTimeMaster()">⏱ Cycle Time Master</button>`:''}<button class="subtab" onclick="go('dwm')">📅 Daily Work Management</button></div>
 <div class="stats stylish-stats"><div class="stat"><div class="icon">🗓️</div><div class="n">${counts.planned}</div><div class="l">Open Plans</div></div><div class="stat"><div class="icon">⚠️</div><div class="n">${counts.overdue}</div><div class="l">Overdue</div></div><div class="stat"><div class="icon">✓</div><div class="n">${counts.completed}</div><div class="l">Completed</div></div></div>
 <div class="panel"><div class="searchbar"><input id="scan_plan_q" placeholder="Search customer, part, tooling, activity..." oninput="filterScanPlans()"><select id="scan_plan_status" onchange="filterScanPlans()"><option value="">All Status</option><option>Planned</option><option>In Process</option><option>Completed</option><option>Overdue</option><option>On Hold</option><option>Cancelled</option></select><select id="scan_plan_plant" onchange="filterScanPlans()"><option value="">All Plants / Units</option>${PLANT_MASTER.map(([v,l])=>`<option value="${v}">${esc(l)}</option>`).join('')}</select></div><div id="scan_plan_rows"></div></div>`;
