const DWM_PLANTS=['Corporate Office','MEPL U1 Plant','MEPL U2 Plant','MEPL U3 Plant','DI Plant','MFPL Plant','Powder Coating Plant','H25 Plant','MSL Plant','2020 – Powder Coating (Bajaj/BAL Line)','2050 – Sigma (TVS Line)','2070 – Siddharth Engineering (Hero Line)'];
const DWM_DEPARTMENTS=['Quality Assurance','Development','HR','Production','Foundry','Maintenance','Stores','Purchase','Planning','Tool Room','Machining','Finance','IT','Other'];
function dwmPlantOptions(selected=''){return DWM_PLANTS.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('')}
function dwmDepartmentOptions(selected=''){return DWM_DEPARTMENTS.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('')}
function dwmShiftConfig(name){return ({
 '1st Shift':{start:'08:00',end:'16:00',breaks:'Lunch 12:30–13:00 • Tea 15 min',breakMinutes:45},
 '2nd Shift':{start:'16:00',end:'00:00',breaks:'Lunch 20:00–20:30',breakMinutes:30},
 '3rd Shift':{start:'00:00',end:'08:00',breaks:'Rest 04:00–04:30 • No lunch',breakMinutes:30},
 'General Shift':{start:'09:00',end:'18:00',breaks:'Lunch 13:30–14:00',breakMinutes:30}
})[name]||null}
function dwmShiftOptions(selected){return ['1st Shift','2nd Shift','3rd Shift','General Shift'].map(v=>`<option value="${v}" ${v===selected?'selected':''}>${v}</option>`).join('')}
function dwmMinutesBetween(a,b){let [ah,am]=a.split(':').map(Number),[bh,bm]=b.split(':').map(Number),x=ah*60+am,y=bh*60+bm;if(y<=x)y+=1440;return y-x}
function applyDwmShift(){const c=dwmShiftConfig($('dwm_shift')?.value);if(!c)return;if($('dwm_shift_time'))$('dwm_shift_time').value=`${c.start} – ${c.end}`;if($('dwm_breaks'))$('dwm_breaks').value=c.breaks;if($('dwm_available'))$('dwm_available').value=dwmMinutesBetween(c.start,c.end)-c.breakMinutes;if($('dwm_start')&&!$('dwm_start').value)$('dwm_start').value=c.start;if($('dwm_end')&&!$('dwm_end').value)$('dwm_end').value=c.end}
function prepareDwmShiftPlan(){const c=dwmShiftConfig($('dwm_shift')?.value);if(!c)return;const available=dwmMinutesBetween(c.start,c.end)-c.breakMinutes;if($('dwm_start'))$('dwm_start').value=c.start;if($('dwm_end'))$('dwm_end').value=c.end;if($('dwm_minutes'))$('dwm_minutes').value=available;if($('dwm_details')){const old=$('dwm_details').value.trim();$('dwm_details').value=(old?old+'\n':'')+`Shift plan: ${c.start}–${c.end}. Breaks: ${c.breaks}. Net available working time: ${available} min.`;}alert(`Shift plan prepared. Net available working time: ${available} minutes.`)}
function applyDwmCycleTime(){const c=cycleTimeForMaterial($('dwm_material')?.value||''),qty=Number($('dwm_qty')?.value||0);if($('dwm_cycle'))$('dwm_cycle').value=c?c.total_time_min:'';if(c&&$('dwm_minutes')&&qty>0)$('dwm_minutes').value=(Number(c.total_time_min||0)*qty).toFixed(1).replace(/\.0$/,'');const shift=$('dwm_shift')?.value||'1st Shift',cfg=dwmShiftConfig(shift),avail=cfg?dwmMinutesBetween(cfg.start,cfg.end)-cfg.breakMinutes:0,planned=Number($('dwm_minutes')?.value||0);if($('dwm_capacity_warning'))showDwmCapacityAlert(false)}
async function saveDwm(e){e.preventDefault();const uid=$('dwm_assignee').value;let u=(window._dwmUsers||[]).find(x=>String(x.id)===String(uid))||currentProfile;const shift=$('dwm_shift')?.value||'1st Shift',c=dwmShiftConfig(shift);const o={work_date:$('dwm_date').value,assigned_to:uid,assigned_name:u?.employee_name||currentProfile?.employee_name,assigned_employee_id:u?.employee_id||currentProfile?.employee_id,department:$('dwm_dept').value,plant_unit:$('dwm_plant').value,assigned_by:$('dwm_assigned_by')?.value||currentUser.id,assigned_by_name:((window._dwmUsers||[]).find(x=>String(x.id)===String($('dwm_assigned_by')?.value))||currentProfile)?.employee_name||currentProfile?.employee_name,task_title:$('dwm_title').value,task_details:$('dwm_details').value,customer_name:$('dwm_customer').value,material_type:$('dwm_material').value,unit:$('dwm_unit').value,quantity:+$('dwm_qty').value||0,cycle_time_min:+$('dwm_cycle').value||null,priority:$('dwm_priority').value,planned_start:$('dwm_start').value||null,planned_end:$('dwm_end').value||null,planned_minutes:+$('dwm_minutes').value||0,shift_name:shift,shift_start:c?.start||null,shift_end:c?.end||null,break_schedule:c?.breaks||'',available_minutes:c?dwmMinutesBetween(c.start,c.end)-c.breakMinutes:null,created_by:currentUser.id,updated_by:currentUser.id};let r=await sb.from('portal_daily_work_management').insert(o).select().single();if(r.error){if(/column .* does not exist/i.test(r.error.message))return alert('Please run PORTAL_V16_2_SHIFT_DWM.sql in Supabase first.');return alert(r.error.message)}closeM();dwm()}
function dwmTab(tab){window._dwmTab=tab||'daily';if(window._dwmTab==='advanced')renderAdvancedDwmBooking();else renderDwm()}
function renderAdvancedDwmBooking(){const users=window._dwmUsers||[],me=currentProfile,tomorrow=nextWorkingDay(dwmLocalDate()),assigned=currentUser.id;$('main').innerHTML=`<div class="page-title"><div><h1>🗓 Advanced DWM Slot Booking</h1><p>Plan future scanning work in advance. Plant users can book tomorrow's DWM tasks before the work is sent to scanning.</p></div><div class="actions-inline"><button class="btn btn-secondary" onclick="dwmTab('daily')">← Daily DWM</button></div></div><div class="dwm-tabs"><button class="dwm-tab" onclick="dwmTab('daily')">Daily Work Management</button><button class="dwm-tab active">Advanced Slot Booking</button></div><div class="panel advanced-booking-panel"><div class="panel-title"><div><h3>＋ Book Future DWM Task</h3><p>Default date is the next working day.</p></div></div><form onsubmit="saveAdvancedDwmBooking(event)"><div class="grid3"><div class="form-group"><label>Planned Work Date</label><input id="adv_date" type="date" min="${tomorrow}" value="${tomorrow}" onchange="applyAdvancedCycleTime()" required></div><div class="form-group"><label>Assigned Engineer</label>${admin()?`<select id="adv_assignee" onchange="applyAdvancedCycleTime()">${users.map(u=>`<option value="${esc(u.id)}" ${String(u.id)===String(assigned)?'selected':''}>${esc(u.employee_name)} (${esc(u.employee_id||'')})</option>`).join('')}</select>`:`<input value="${esc(me?.employee_name||'')}" readonly><input type="hidden" id="adv_assignee" value="${esc(currentUser.id)}">`}</div><div class="form-group"><label>Assigned By</label><input value="${esc(me?.employee_name||'')}" readonly><input type="hidden" id="adv_assigned_by" value="${esc(currentUser.id)}"></div><div class="form-group"><label>Plant / Unit</label><select id="adv_plant">${dwmPlantOptions(me?.plant_unit||'')}</select></div><div class="form-group"><label>Department</label><select id="adv_dept">${dwmDepartmentOptions(me?.department||'')}</select></div><div class="form-group"><label>Customer</label><input id="adv_customer" placeholder="Customer Name"></div><div class="form-group"><label>Material Type</label><select id="adv_material" onchange="applyAdvancedCycleTime()">${cycleMaterialOptions('')}</select></div><div class="form-group"><label>Unit</label><select id="adv_unit">${dwmUnitOptions('Nos')}</select></div><div class="form-group"><label>Quantity</label><input id="adv_qty" type="number" min="0" step="0.01" value="1" oninput="applyAdvancedCycleTime()"></div><div class="form-group"><label>Cycle Time / Unit (min)</label><input id="adv_cycle" type="number" readonly></div><div class="form-group"><label>Shift</label><select id="adv_shift" onchange="applyAdvancedCycleTime()">${dwmShiftOptions('1st Shift')}</select></div><div class="form-group"><label>Planned Minutes</label><input id="adv_minutes" type="number" min="0" readonly><span id="adv_capacity_warning" class="field-hint"></span></div><div class="form-group"><label>Priority</label><select id="adv_priority">${['Low','Medium','High','Critical'].map(v=>`<option ${v==='Medium'?'selected':''}>${v}</option>`).join('')}</select></div><div class="form-group"><label>Task Title</label><input id="adv_title" required placeholder="e.g. 3D Scanning – Customer Part"></div><div class="form-group full"><label>Task Details / Expected Result</label><textarea id="adv_details" placeholder="Part / drawing / scanning requirement"></textarea></div></div><div class="shift-plan-note"><b>Advance Planning Rule:</b> This booking creates the selected future date as a DWM task immediately, so the scanning team can see tomorrow's planned work in advance.</div><div class="actions"><button type="button" class="btn btn-secondary" onclick="dwmTab('daily')">Cancel</button><button class="btn btn-primary">🗓 Book Future DWM Slot</button></div></form></div><div class="panel"><div class="panel-title"><div><h3>📋 Upcoming Advanced Bookings</h3><p>Future bookings created through this tab.</p></div></div><div class="tablewrap"><table><thead><tr><th>Date</th><th>Engineer</th><th>Plant</th><th>Shift</th><th>Task</th><th>Planned Minutes</th><th>Status</th></tr></thead><tbody id="adv_booking_rows"><tr><td colspan="7" class="empty">Loading bookings...</td></tr></tbody></table></div></div>`;applyAdvancedCycleTime();loadAdvancedBookings()}
function applyAdvancedCycleTime(){const c=cycleTimeForMaterial($('adv_material')?.value||''),qty=Number($('adv_qty')?.value||0);if($('adv_cycle'))$('adv_cycle').value=c?c.total_time_min:'';const planned=(Number(c?.total_time_min)||0)*qty;if($('adv_minutes'))$('adv_minutes').value=planned;const shift=$('adv_shift')?.value||'1st Shift',uid=$('adv_assignee')?.value||currentUser.id,date=$('adv_date')?.value||nextWorkingDay(dwmLocalDate()),cap=dwmCapacityFor(uid,date,shift),total=cap.existing+planned,diff=total-cap.available;if($('adv_capacity_warning'))$('adv_capacity_warning').innerHTML=diff>0?`<span class="capacity-warning">🔴 OVERLOAD: ${total} min / ${cap.available} min. Over by ${diff} min.</span>`:`<span class="capacity-short">🟡 ${total} min / ${cap.available} min. ${Math.max(0,cap.available-total)} min capacity remains.</span>`}
