async function rejectExportRequest(id){if(!admin())return;const remark=prompt('Reason for rejection?','');if(remark===null)return;const r=await sb.from('portal_export_requests').update({status:'Rejected',admin_remarks:remark}).eq('id',id);if(r.error)return alert(r.error.message);adminExportRequests();}

/* ========================= V22: OEE + DIGITAL LAYOUT INSPECTION ========================= */
function v22Num(id){return Number($(id)?.value||0)}
function v22Pct(n){return Number.isFinite(n)?n.toFixed(2)+'%':'0.00%'}
function v22Esc(v){return esc(v==null?'':String(v))}
function oee(){
  $('main').innerHTML=`<div class="page-title"><div><h1>📈 OEE Generic Calculator</h1><p>Standardized OEE calculation with traceable history.</p></div><div class="actions-inline"><button class="btn btn-secondary" onclick="loadOeeHistory()">↻ Refresh History</button></div></div>
  <div class="v22-grid">
   <div class="panel"><div class="panel-title"><div><h3>OEE Input</h3><p>Enter actual production data.</p></div></div>
   <form onsubmit="saveOee(event)" class="grid3">
    <div class="form-group"><label>Date</label><input id="oee_date" type="date" value="${dwmLocalDate()}"></div>
    <div class="form-group"><label>Plant / Unit</label><select id="oee_plant"><option value="">Select Plant / Unit</option>${PLANT_MASTER.map(([v,l])=>`<option value="${v}">${esc(l)}</option>`).join('')}</select></div>
    <div class="form-group"><label>Department</label><input id="oee_dept" placeholder="Department"></div>
    <div class="form-group"><label>Machine / Process</label><input id="oee_machine" placeholder="Machine / Process"></div>
    <div class="form-group"><label>Shift</label><select id="oee_shift"><option>1st Shift</option><option>2nd Shift</option><option>3rd Shift</option><option>General Shift</option></select></div>
    <div class="form-group"><label>Planned Production Time (min)</label><input id="oee_planned" type="number" min="0" step="0.01" required oninput="calcOee()"></div>
    <div class="form-group"><label>Downtime (min)</label><input id="oee_down" type="number" min="0" step="0.01" value="0" oninput="calcOee()"></div>
    <div class="form-group"><label>Ideal Cycle Time (sec/part)</label><input id="oee_cycle" type="number" min="0" step="0.01" required oninput="calcOee()"></div>
    <div class="form-group"><label>Total Count</label><input id="oee_total" type="number" min="0" step="1" required oninput="calcOee()"></div>
    <div class="form-group"><label>Good Count</label><input id="oee_good" type="number" min="0" step="1" required oninput="calcOee()"></div>
    <div class="form-group"><label>Reject Count</label><input id="oee_reject" type="number" min="0" step="1" readonly></div>
    <div class="form-group full"><label>Remarks</label><textarea id="oee_remarks" placeholder="Reason / observation / action"></textarea></div>
    <div class="form-group full"><div class="v22-oee-results"><div><span>Availability</span><b id="oee_av">0.00%</b></div><div><span>Performance</span><b id="oee_perf">0.00%</b></div><div><span>Quality</span><b id="oee_qual">0.00%</b></div><div class="oee-total"><span>OEE</span><b id="oee_result">0.00%</b></div></div></div>
    <div class="actions full"><button type="button" class="btn btn-secondary" onclick="calcOee()">Calculate</button><button class="btn btn-primary">Save OEE Record</button></div>
   </form></div>
   <div class="panel"><div class="panel-title"><div><h3>Calculation Formula</h3><p>Standard OEE relationship.</p></div></div>
    <div class="formula-card"><b>Availability</b><span>Operating Time ÷ Planned Production Time</span><b>Performance</b><span>(Ideal Cycle Time × Total Count) ÷ Operating Time</span><b>Quality</b><span>Good Count ÷ Total Count</span><b>OEE</b><span>Availability × Performance × Quality</span></div>
   </div>
  </div>
  <div class="panel"><div class="panel-title"><div><h3>🗂 OEE Calculation History</h3><p>Traceable records. Authorized users can update or delete permitted records.</p></div></div><div class="tablewrap"><table><thead><tr><th>Date</th><th>Plant</th><th>Machine / Process</th><th>Shift</th><th>Availability</th><th>Performance</th><th>Quality</th><th>OEE</th><th>User</th><th>Action</th></tr></thead><tbody id="oee_history_rows"><tr><td colspan="10" class="empty">Loading...</td></tr></tbody></table></div></div>`;
  calcOee();loadOeeHistory();
}
function calcOee(){
 const planned=v22Num('oee_planned'),down=v22Num('oee_down'),cycle=v22Num('oee_cycle'),total=v22Num('oee_total'),good=v22Num('oee_good'),op=Math.max(0,planned-down);
 const av=planned?Math.min(100,op/planned*100):0,perf=op&&cycle&&total?Math.min(100,(cycle*total)/(op*60)*100):0,qual=total?Math.min(100,good/total*100):0,oee=av*perf*qual/10000;
 if($('oee_reject'))$('oee_reject').value=Math.max(0,total-good);
 if($('oee_av'))$('oee_av').textContent=v22Pct(av);if($('oee_perf'))$('oee_perf').textContent=v22Pct(perf);if($('oee_qual'))$('oee_qual').textContent=v22Pct(qual);if($('oee_result'))$('oee_result').textContent=v22Pct(oee);
 return {planned,down,op,cycle,total,good,reject:Math.max(0,total-good),av,perf,qual,oee};
}
async function saveOee(e){
 e.preventDefault();const c=calcOee(),o={calculation_date:$('oee_date').value,plant_unit:$('oee_plant').value.trim(),department:$('oee_dept').value.trim(),machine_process:$('oee_machine').value.trim(),shift_name:$('oee_shift').value,planned_production_min:c.planned,downtime_min:c.down,operating_time_min:c.op,ideal_cycle_time_sec:c.cycle,total_count:c.total,good_count:c.good,reject_count:c.reject,availability_pct:c.av,performance_pct:c.perf,quality_pct:c.qual,oee_pct:c.oee,remarks:$('oee_remarks').value,created_by:currentUser.id,created_by_name:currentProfile?.employee_name||'',updated_by:currentUser.id};
 let r;
 if(window._oeeEditId){
   r=await sb.from('portal_oee_calculation_history').update({...o,updated_at:new Date().toISOString()}).eq('id',window._oeeEditId);
   window._oeeEditId=null;
 }else{
   r=await sb.from('portal_oee_calculation_history').insert(o);
 }
 if(r.error)return alert(r.error.message);alert('OEE calculation saved successfully.');loadOeeHistory();
}
async function loadOeeHistory(){
 const el=$('oee_history_rows');if(!el)return;let q=sb.from('portal_oee_calculation_history').select('*').order('calculation_date',{ascending:false}).order('id',{ascending:false});const r=await q;if(r.error){el.innerHTML=`<tr><td colspan="10" class="empty">${v22Esc(r.error.message)}</td></tr>`;return}
 el.innerHTML=(r.data||[]).map(x=>`<tr><td>${v22Esc(x.calculation_date)}</td><td>${v22Esc(x.plant_unit||'-')}</td><td>${v22Esc(x.machine_process||'-')}</td><td>${v22Esc(x.shift_name||'-')}</td><td>${v22Pct(x.availability_pct)}</td><td>${v22Pct(x.performance_pct)}</td><td>${v22Pct(x.quality_pct)}</td><td><b>${v22Pct(x.oee_pct)}</b></td><td>${v22Esc(x.created_by_name||'-')}</td><td>${(admin()||x.created_by===currentUser.id)?`<button class="btn btn-secondary" onclick="editOee(${x.id})">Update</button> <button class="btn btn-danger" onclick="deleteOee(${x.id})">Delete</button>`:'View only'}</td></tr>`).join('')||'<tr><td colspan="10" class="empty">No OEE history.</td></tr>';
}
async function editOee(id){
 const r=await sb.from('portal_oee_calculation_history').select('*').eq('id',id).single();if(r.error)return alert(r.error.message);const x=r.data;
 $('oee_date').value=x.calculation_date||'';$('oee_plant').value=x.plant_unit||'';$('oee_dept').value=x.department||'';$('oee_machine').value=x.machine_process||'';$('oee_shift').value=x.shift_name||'1st Shift';$('oee_planned').value=x.planned_production_min||0;$('oee_down').value=x.downtime_min||0;$('oee_cycle').value=x.ideal_cycle_time_sec||0;$('oee_total').value=x.total_count||0;$('oee_good').value=x.good_count||0;$('oee_remarks').value=x.remarks||'';calcOee();window._oeeEditId=id;document.querySelector('.oee-total')?.scrollIntoView({behavior:'smooth'});
}
async function deleteOee(id){if(!confirm('Delete this OEE calculation record?'))return;const r=await sb.from('portal_oee_calculation_history').delete().eq('id',id);if(r.error)return alert(r.error.message);loadOeeHistory()}

function layout(){
 $('main').innerHTML=`<div class="page-title"><div><h1>📐 Digital Layout Inspection Report</h1><p>Controlled dimensional inspection record with preparation, checking, approval and revision traceability.</p></div><div class="actions-inline"><button class="btn btn-secondary" onclick="loadLayoutHistory()">↻ Refresh History</button></div></div>
 <div class="panel"><div class="panel-title"><div><h3>New Layout Inspection Report</h3><p>Enter controlled report header and inspection characteristics.</p></div></div>
 <form onsubmit="saveLayout(event)"><div class="grid3">
 <div class="form-group"><label>Report No.</label><input id="li_report" value="LI-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}" readonly></div>
 <div class="form-group"><label>Inspection Date</label><input id="li_date" type="date" value="${dwmLocalDate()}" required></div>
 <div class="form-group"><label>Plant / Unit</label><select id="li_plant"><option value="">Select Plant / Unit</option>${PLANT_MASTER.map(([v,l])=>`<option value="${v}">${esc(l)}</option>`).join('')}</select></div>
 <div class="form-group"><label>Customer</label><input id="li_customer" placeholder="Customer Name"></div>
 <div class="form-group"><label>Part Name</label><input id="li_part" placeholder="Part Name" required></div>
 <div class="form-group"><label>Part No.</label><input id="li_partno" placeholder="Part No." required></div>
 <div class="form-group"><label>Drawing No.</label><input id="li_drawing" placeholder="Drawing No." required></div>
 <div class="form-group"><label>Drawing Revision</label><input id="li_rev" placeholder="Revision" required></div>
 <div class="form-group"><label>Sample Quantity</label><input id="li_qty" type="number" min="1" value="1"></div>
 <div class="form-group"><label>Inspection Reason</label><select id="li_reason"><option>Initial Layout Inspection</option><option>Annual Layout Inspection</option><option>Engineering Change / Revision</option><option>Customer Requirement</option><option>Re-validation</option><option>Other</option></select></div>
 <div class="form-group"><label>Inspector</label><input id="li_inspector" value="${v22Esc(currentProfile?.employee_name||'')}"></div>
 <div class="form-group"><label>Instrument / Gauge</label><input id="li_instrument" placeholder="CMM / VMM / Micrometer / Gauge"></div>
 <div class="form-group"><label>Calibration Status</label><select id="li_cal"><option>Valid</option><option>Expired</option><option>Not Applicable</option></select></div>
 <div class="form-group"><label>Initial Status</label><select id="li_status"><option>Draft</option><option>Prepared</option></select></div>
 <div class="form-group full"><label>Remarks</label><textarea id="li_remarks"></textarea></div>
 </div>
 <div class="panel-sub"><h3>Inspection Characteristics</h3><p>Add dimensions/CTQs and actual results.</p><div class="tablewrap"><table class="v22-edit-table"><thead><tr><th>No.</th><th>Description</th><th>Specification</th><th>Nominal</th><th>Lower</th><th>Upper</th><th>Actual</th><th>Unit</th><th>Instrument</th><th>Result</th><th></th></tr></thead><tbody id="li_chars"></tbody></table></div><button type="button" class="btn btn-secondary" onclick="addLayoutChar()">＋ Add Characteristic</button></div>
 <div class="actions"><button type="button" class="btn btn-secondary" onclick="go('layout')">Reset</button><button class="btn btn-primary">Save Layout Inspection Report</button></div></form></div>
 <div class="panel"><div class="panel-title"><div><h3>🗂 Inspection History</h3><p>Searchable controlled records and approval status.</p></div></div><div class="tablewrap"><table><thead><tr><th>Report No.</th><th>Date</th><th>Customer</th><th>Part</th><th>Drawing / Rev.</th><th>Status</th><th>Approval</th><th>Prepared By</th><th>Action</th></tr></thead><tbody id="layout_history_rows"><tr><td colspan="9" class="empty">Loading...</td></tr></tbody></table></div></div>`;
 addLayoutChar();loadLayoutHistory();
}
function addLayoutChar(){
 const tb=$('li_chars');if(!tb)return;const n=tb.children.length+1;tb.insertAdjacentHTML('beforeend',`<tr data-row="${n}"><td>${n}</td><td><input class="lic-desc" placeholder="Characteristic / CTQ"></td><td><input class="lic-spec" placeholder="As per drawing"></td><td><input class="lic-nom" type="number" step="0.001"></td><td><input class="lic-low" type="number" step="0.001"></td><td><input class="lic-up" type="number" step="0.001"></td><td><input class="lic-act" type="number" step="0.001"></td><td><input class="lic-unit" placeholder="mm"></td><td><input class="lic-inst" placeholder="Instrument"></td><td><select class="lic-result"><option>Pending</option><option>OK</option><option>NG</option></select></td><td><button type="button" class="btn btn-danger" onclick="this.closest('tr').remove()">×</button></td></tr>`);
}
function collectLayoutChars(){return [...document.querySelectorAll('#li_chars tr')].map((tr,i)=>({characteristic_no:String(i+1),characteristic_description:tr.querySelector('.lic-desc')?.value||'',specification:tr.querySelector('.lic-spec')?.value||'',nominal_value:parseFloat(tr.querySelector('.lic-nom')?.value)||null,lower_limit:parseFloat(tr.querySelector('.lic-low')?.value)||null,upper_limit:parseFloat(tr.querySelector('.lic-up')?.value)||null,actual_value:parseFloat(tr.querySelector('.lic-act')?.value)||null,unit:tr.querySelector('.lic-unit')?.value||'',instrument:tr.querySelector('.lic-inst')?.value||'',result:tr.querySelector('.lic-result')?.value||'Pending',sequence_no:i+1})).filter(x=>x.characteristic_description||x.specification||x.actual_value!==null)}
async function saveLayout(e){
 e.preventDefault();const o={report_no:$('li_report').value,inspection_date:$('li_date').value,plant_unit:$('li_plant').value,customer_name:$('li_customer').value,part_name:$('li_part').value,part_no:$('li_partno').value,drawing_no:$('li_drawing').value,drawing_revision:$('li_rev').value,sample_qty:Number($('li_qty').value||1),inspection_reason:$('li_reason').value,inspector_name:$('li_inspector').value,instrument_name:$('li_instrument').value,calibration_status:$('li_cal').value,status:$('li_status').value,approval_status:'Prepared',prepared_by:currentUser.id,prepared_by_name:currentProfile?.employee_name||'',remarks:$('li_remarks').value};
 const r=await sb.from('portal_layout_inspection_reports').insert(o).select().single();if(r.error)return alert(r.error.message);const chars=collectLayoutChars().map(x=>({...x,report_id:r.data.id}));if(chars.length){const cr=await sb.from('portal_layout_inspection_characteristics').insert(chars);if(cr.error){await sb.from('portal_layout_inspection_reports').delete().eq('id',r.data.id);return alert(cr.error.message)}}alert(`Layout Inspection Report ${o.report_no} saved as Prepared record.`);layout();
}
async function loadLayoutHistory(){
 const el=$('layout_history_rows');if(!el)return;const r=await sb.from('portal_layout_inspection_reports').select('*').order('inspection_date',{ascending:false}).order('id',{ascending:false});if(r.error){el.innerHTML=`<tr><td colspan="9" class="empty">${v22Esc(r.error.message)}</td></tr>`;return}
 el.innerHTML=(r.data||[]).map(x=>`<tr><td><b>${v22Esc(x.report_no)}</b></td><td>${v22Esc(x.inspection_date)}</td><td>${v22Esc(x.customer_name||'-')}</td><td>${v22Esc(x.part_name||'-')}<br><small>${v22Esc(x.part_no||'')}</small></td><td>${v22Esc(x.drawing_no||'')} / ${v22Esc(x.drawing_revision||'')}</td><td>${v22Esc(x.status||'-')}</td><td>${v22Esc(x.approval_status||'-')}</td><td>${v22Esc(x.prepared_by_name||'-')}</td><td><button class="btn btn-secondary" onclick="viewLayout(${x.id})">View</button>${(admin()||x.prepared_by===currentUser.id)&&x.approval_status!=='Approved'?` <button class="btn btn-danger" onclick="deleteLayout(${x.id})">Delete</button>`:''}${admin()&&x.approval_status!=='Approved'?` <button class="btn btn-primary" onclick="approveLayout(${x.id})">Approve</button>`:''}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">No inspection reports.</td></tr>';
}
async function viewLayout(id){
 const r=await sb.from('portal_layout_inspection_reports').select('*').eq('id',id).single();if(r.error)return alert(r.error.message);const c=await sb.from('portal_layout_inspection_characteristics').select('*').eq('report_id',id).order('sequence_no');if(c.error)return alert(c.error.message);
 const x=r.data, rows=c.data||[];$('app').insertAdjacentHTML('beforeend',`<div class="modal-bg" id="modal"><div class="modal modal-wide"><div class="modal-header"><div><h2>${v22Esc(x.report_no)} — Layout Inspection</h2><p class="small">${v22Esc(x.part_name)} • ${v22Esc(x.drawing_no)} Rev ${v22Esc(x.drawing_revision)}</p></div><button class="close" onclick="closeM()">×</button></div><div class="report-header-grid">${[['Customer',x.customer_name],['Plant',x.plant_unit],['Date',x.inspection_date],['Reason',x.inspection_reason],['Inspector',x.inspector_name],['Calibration',x.calibration_status],['Status',x.status],['Approval',x.approval_status]].map(a=>`<div><span>${v22Esc(a[0])}</span><b>${v22Esc(a[1]||'-')}</b></div>`).join('')}</div><div class="tablewrap"><table><thead><tr><th>No.</th><th>Description</th><th>Specification</th><th>Nominal</th><th>Lower</th><th>Upper</th><th>Actual</th><th>Unit</th><th>Result</th></tr></thead><tbody>${rows.map(q=>`<tr><td>${v22Esc(q.characteristic_no)}</td><td>${v22Esc(q.characteristic_description)}</td><td>${v22Esc(q.specification)}</td><td>${q.nominal_value??''}</td><td>${q.lower_limit??''}</td><td>${q.upper_limit??''}</td><td>${q.actual_value??''}</td><td>${v22Esc(q.unit)}</td><td>${v22Esc(q.result)}</td></tr>`).join('')}</tbody></table></div><div class="actions"><button class="btn btn-secondary" onclick="closeM()">Close</button></div></div></div>`);
}
async function approveLayout(id){
 if(!admin())return alert('Only an authorized approver can approve this report.');
 if(!confirm('Approve and release this layout inspection report?'))return;
 const r=await sb.from('portal_layout_inspection_reports').update({approval_status:'Approved',status:'Released',approved_by:currentUser.id,approved_by_name:currentProfile?.employee_name||'',approved_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',id);
 if(r.error)return alert(r.error.message);alert('Layout inspection report approved and released.');loadLayoutHistory();
}
async function deleteLayout(id){if(!confirm('Delete this draft/prepared layout inspection record?'))return;const r=await sb.from('portal_layout_inspection_reports').delete().eq('id',id);if(r.error)return alert(r.error.message);loadLayoutHistory()}
